SELECT id, symbol, status, started_at, anchor_entry_price, best_entry_price, latest_signal_id, evidence_count, buy_count, watch_count, evidence_score, opportunity_health, five_minute_decision, one_hour_decision, execution_source, recommended_position_percent, decision_code, executed_at FROM execution_opportunity WHERE latest_signal_id IN (156723,165412,167668,171589,176710,159408) ORDER BY id LIMIT 20